    "": "2677",
    "Exercise Name": "Single-arm landmine press",
    "Desc": "The single-arm landmine press is an upper-body exercise that uses an angled barbell anchored at floor level in a landmine device. It can also be performed by sticking a barbell in the corner of a room",
    "Type": "preferably in a towel to protect the walls. The angle of a landmine press is usually somewhere between an incline press and a military press",
